const rows = $json.data ?? [];

if (!Array.isArray(rows)) {
  throw new Error(
    'Respuesta inesperada de Directus'
  );
}

const now = new Date();

function contactLabel(contact) {
  if (!contact) {
    return 'Sin contacto';
  }

  const name = [
    contact.first_name,
    contact.last_name
  ]
    .filter(Boolean)
    .join(' ')
    .trim();

  if (contact.company && name) {
    return `${contact.company} · ${name}`;
  }

  return (
    contact.company ||
    name ||
    'Sin contacto'
  );
}

function isSameLocalDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function tomorrowFrom(date) {
  const result = new Date(date);
  result.setDate(result.getDate() + 1);
  return result;
}

function dayState(startAt) {
  const start = new Date(startAt);

  if (Number.isNaN(start.getTime())) {
    return {
      state: 'invalid',
      label: 'Fecha inválida'
    };
  }

  if (isSameLocalDay(start, now)) {
    return {
      state: 'today',
      label: 'Hoy'
    };
  }

  if (
    isSameLocalDay(
      start,
      tomorrowFrom(now)
    )
  ) {
    return {
      state: 'tomorrow',
      label: 'Mañana'
    };
  }

  return {
    state: 'upcoming',
    label: 'Próxima'
  };
}

const appointments = rows.map(appointment => {
  const timing = dayState(
    appointment.start_at
  );

  return {
    id: appointment.id,

    title:
      appointment.title ?? null,

    start_at:
      appointment.start_at ?? null,

    end_at:
      appointment.end_at ?? null,

    status:
      appointment.status ?? null,

    timing_state:
      timing.state,

    timing_label:
      timing.label,

    notes:
      appointment.notes ?? null,

    source:
      appointment.source ?? null,

    external_provider:
      appointment.external_provider ?? null,

    external_event_id:
      appointment.external_event_id ?? null,

    contact:
      appointment.contact_id
        ? {
            id:
              appointment.contact_id.id,

            first_name:
              appointment.contact_id.first_name ?? null,

            last_name:
              appointment.contact_id.last_name ?? null,

            company:
              appointment.contact_id.company ?? null,

            email:
              appointment.contact_id.email ?? null,

            label:
              contactLabel(
                appointment.contact_id
              )
          }
        : null
  };
});

const summary = {
  total: appointments.length,

  today:
    appointments.filter(
      item =>
        item.timing_state === 'today'
    ).length,

  tomorrow:
    appointments.filter(
      item =>
        item.timing_state === 'tomorrow'
    ).length,

  upcoming:
    appointments.filter(
      item =>
        item.timing_state === 'upcoming'
    ).length,

  confirmed:
    appointments.filter(
      item =>
        item.status === 'confirmed'
    ).length,

  scheduled:
    appointments.filter(
      item =>
        item.status === 'scheduled'
    ).length
};

return [
  {
    json: {
      status:
        appointments.length === 0
          ? 'empty'
          : 'ok',

      summary,

      appointments
    }
  }
];

const input = $json;

const clean = (value) => {
  if (value === undefined || value === null) {
    return null;
  }

  const result = String(value).trim();

  return result === ''
    ? null
    : result;
};

const contactId = clean(input.contact_id);

if (contactId) {
  const uuidPattern =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

  if (!uuidPattern.test(contactId)) {
    throw new Error(
      `contact_id no es un UUID válido: ${contactId}`
    );
  }
}

let limit = Number(input.limit ?? 50);

if (
  !Number.isInteger(limit) ||
  limit < 1
) {
  throw new Error(
    `limit inválido: ${input.limit}`
  );
}

limit = Math.min(limit, 100);

const now = new Date().toISOString();

const filter = {
  _and: [
    {
      start_at: {
        _gte: now
      }
    },
    {
      status: {
        _in: [
          'scheduled',
          'confirmed'
        ]
      }
    }
  ]
};

if (contactId) {
  filter._and.push({
    contact_id: {
      _eq: contactId
    }
  });
}

return [
  {
    json: {
      contact_id: contactId,
      limit,
      now,
      filter
    }
  }
];
